PREFIX ins: <http://data.world/schema/insurance/>

SELECT (xsd:decimal(SUM(?amt)) / COUNT(DISTINCT ?policy) AS ?averagePolicySize)
WHERE {
  SERVICE <mapped> {
    ?pcd ins:hasPolicy ?policy ;
         ins:hasPremiumAmount ?premium .
    ?premium ins:premiumAmount ?amt .
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
       (COALESCE(SUM(?lossPaymentVal), 0) + COALESCE(SUM(?lossReserveVal), 0) + COALESCE(SUM(?expensePaymentVal), 0) + COALESCE(SUM(?expenseReserveVal), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?pcd .

    ?pcd a ins:PolicyCoverageDetail ;
         ins:hasPolicy ?policy ;
         ins:hasPremiumAmount ?premium .

    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:hasPolicyHolder ?policyHolder .

    ?policyHolder a ins:PolicyHolder ;
                  ins:policyHolderId ?policyHolderId .

    ?premium a ins:Premium ;
             ins:premiumAmount ?premiumAmount .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lpAmtRaw .
      BIND(xsd:decimal(?lpAmtRaw) AS ?lossPaymentVal)
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lrAmtRaw .
      BIND(xsd:decimal(?lrAmtRaw) AS ?lossReserveVal)
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?epAmtRaw .
      BIND(xsd:decimal(?epAmtRaw) AS ?expensePaymentVal)
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?erAmtRaw .
      BIND(xsd:decimal(?erAmtRaw) AS ?expenseReserveVal)
    }
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
ORDER BY ?claimNumber ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?policyHolderId ?policyNumber (SUM(?premiumValue) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy a ins:Policy ;
            ins:policyNumber ?policyNumber ;
            ins:hasPolicyHolder ?policyHolder .

    ?policyHolder ins:policyHolderId ?policyHolderId .

    ?coverage a ins:PolicyCoverageDetail ;
              ins:hasPolicy ?policy ;
              ins:hasPremiumAmount ?premium .

    ?premium ins:premiumAmount ?premiumValue .
  }
}
GROUP BY ?policyHolderId ?policyNumber
ORDER BY ?policyHolderId ?policyNumber

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid ?catastrophe ?agent
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a ins:Claim ;
           ins:claimNumber ?claimNumber ;
           ins:against ?pcd .

    OPTIONAL {
      ?claim ins:hasLossPayment ?lp .
      ?lp ins:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasLossReserve ?lr .
      ?lr ins:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpensePayment ?ep .
      ?ep ins:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim ins:hasExpenseReserve ?er .
      ?er ins:expenseReserveAmount ?expenseReserveAmount .
    }

    OPTIONAL {
      ?claim ins:hasCatastrophe ?cat .
      OPTIONAL { ?cat ins:catastropheName ?catastropheName . }
      BIND(COALESCE(?catastropheName, STR(?cat)) AS ?catastrophe)
    }

    ?pcd ins:hasPolicy ?policy .

    OPTIONAL { ?policy ins:policyNumber ?policyNumber . }

    OPTIONAL {
      ?policy ins:hasPolicyHolder ?ph .
      OPTIONAL { ?ph ins:policyHolderId ?policyHolderId . }
      BIND(COALESCE(?policyHolderId, STR(?ph)) AS ?policyHolder)
    }

    OPTIONAL {
      ?pcd ins:hasPremiumAmount ?prem .
      ?prem ins:premiumAmount ?premiumAmountPaid .
    }

    OPTIONAL {
      ?policy ins:soldByAgent ?ag .
      OPTIONAL { ?ag ins:agentId ?agentId . }
      BIND(COALESCE(?agentId, STR(?ag)) AS ?agent)
    }
  }
}

PREFIX ins: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy ins:soldByAgent ?agent ;
            ins:policyNumber ?policyNumber .

    ?agent ins:agentId ?agentId .

    ?coverage ins:hasPolicy ?policy .

    ?claim ins:against ?coverage ;
           ins:claimNumber ?claimNumber ;
           ins:hasExpenseReserve ?expenseReserve .

    ?expenseReserve ins:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
